use std::{collections::BTreeSet, time::Instant};
use turso::params;

fn main() {
    tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap()
        .block_on(run()).unwrap();
}

async fn run() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<_> = std::env::args().collect();
    let count: usize = args.get(1).map(|s| s.parse().unwrap()).unwrap_or(65537);
    let modes = args.get(2).map(String::as_str).unwrap_or("original,tuple,rowid,rowid_exists");
    let stride: usize = args.get(3).map(|s| s.parse().unwrap()).unwrap_or(1);
    let directory = tempfile::tempdir()?;
    let path = directory.path().join("state.sqlite");
    let database = turso::Builder::new_local(path.to_str().unwrap())
        .experimental_multiprocess_wal(true).build().await?;
    let mut connection = database.connect()?;
    connection.set_transaction_behavior(turso::transaction::TransactionBehavior::Immediate);
    connection.execute_batch("CREATE TABLE objects(namespace TEXT NOT NULL, native_id BLOB NOT NULL,
        payload BLOB NOT NULL, payload_size BLOB NOT NULL, record BLOB NOT NULL,
        validated INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(namespace,native_id));
        CREATE TEMP TABLE retained_objects(namespace TEXT NOT NULL,native_id BLOB NOT NULL,
        PRIMARY KEY(namespace,native_id));").await?;
    let tx = connection.transaction().await?;
    let mut objects = tx.prepare_cached("INSERT INTO objects VALUES (?1,?2,X'',X'',?3,1)").await?;
    let mut retain = tx.prepare_cached("INSERT INTO retained_objects VALUES (?1,?2)").await?;
    let started = Instant::now();
    let mut expected = BTreeSet::new();
    for index in 0..count {
        let id = blake3::hash(&(index as u64).to_le_bytes());
        objects.execute(params!["casita.blob.v1", id.as_bytes().as_slice(), vec![42_u8; 64]]).await?;
        if index % stride == 0 {
            retain.execute(params!["casita.blob.v1", id.as_bytes().as_slice()]).await?;
            expected.insert(id.as_bytes().to_vec());
        }
    }
    println!("sql_profile {}", serde_json::json!({"phase":"seed", "count":count,"stride":stride,"nanos":started.elapsed().as_nanos()}));
    let mut first = tx.prepare_cached("EXPLAIN QUERY PLAN SELECT o.rowid,o.namespace,o.native_id,o.record FROM objects o NOT INDEXED JOIN retained_objects r ON r.namespace=o.namespace AND r.native_id=o.native_id ORDER BY o.rowid LIMIT 256").await?;
    let mut first_rows = first.query(()).await?;
    let mut details = Vec::new();
    while let Some(row) = first_rows.next().await? { details.push(row.get::<String>(3)?); }
    println!("sql_profile {}", serde_json::json!({"phase":"plan", "mode":"rowid_first_page", "details":details}));
    let midpoint = expected.iter().nth(expected.len()/2).unwrap().clone();
    for mode in modes.split(',') {
        let sql = match mode {
            "original" => "SELECT o.namespace,o.native_id,o.record,o.rowid FROM objects o JOIN retained_objects r
                ON r.namespace=o.namespace AND r.native_id=o.native_id
                WHERE o.namespace > ?1 OR (o.namespace = ?1 AND o.native_id > ?2)
                ORDER BY o.namespace,o.native_id LIMIT 256",
            "tuple" => "SELECT o.namespace,o.native_id,o.record,o.rowid FROM objects o JOIN retained_objects r
                ON r.namespace=o.namespace AND r.native_id=o.native_id
                WHERE (o.namespace,o.native_id) > (?1,?2)
                ORDER BY o.namespace,o.native_id LIMIT 256",
            "rowid" => "SELECT o.namespace,o.native_id,o.record,o.rowid FROM objects o NOT INDEXED JOIN retained_objects r
                ON r.namespace=o.namespace AND r.native_id=o.native_id
                WHERE o.rowid > ?1 ORDER BY o.rowid LIMIT 256",
            "rowid_exists" => "SELECT o.namespace,o.native_id,o.record,o.rowid FROM objects o
                WHERE o.rowid > ?1 AND EXISTS (SELECT 1 FROM retained_objects r
                    WHERE r.namespace=o.namespace AND r.native_id=o.native_id)
                ORDER BY o.rowid LIMIT 256",
            _ => panic!("unknown mode"),
        };
        let explain = format!("EXPLAIN QUERY PLAN {sql}");
        let mut plan = tx.prepare_cached(&explain).await?;
        let mut rows = if mode.starts_with("rowid") {
            plan.query(params![(count/2) as i64]).await?
        } else { plan.query(params!["casita.blob.v1",midpoint.clone()]).await? };
        let mut details = Vec::new();
        while let Some(row) = rows.next().await? { details.push(row.get::<String>(3)?); }
        println!("sql_profile {}", serde_json::json!({"phase":"plan", "mode":mode,"details":details}));
        for iteration in 0..2 {
            let mut statement = tx.prepare_cached(sql).await?;
            let mut key = Vec::new();
            let mut rowid = 0_i64;
            let mut observed = BTreeSet::new();
            let mut pages = Vec::new();
            let started = Instant::now();
            loop {
                let page_start = Instant::now();
                let mut rows = if mode.starts_with("rowid") {
                    statement.query(params![rowid]).await?
                } else { statement.query(params!["casita.blob.v1",key.clone()]).await? };
                let mut fetched = 0;
                while let Some(row) = rows.next().await? {
                    key = row.get::<Vec<u8>>(1)?;
                    let record = row.get::<Vec<u8>>(2)?;
                    rowid = row.get::<i64>(3)?;
                    assert_eq!(record, vec![42; 64]);
                    assert!(observed.insert(key.clone()));
                    fetched += 1;
                }
                pages.push(page_start.elapsed().as_nanos() as u64);
                if fetched == 0 { break; }
            }
            let nanos = started.elapsed().as_nanos();
            assert_eq!(observed, expected);
            println!("sql_profile {}", serde_json::json!({"phase":"scan","mode":mode,"iteration":iteration,
                "count":count,"retained":expected.len(),"stride":stride,"nanos":nanos,"pages":pages}));
        }
    }
    tx.rollback().await?;
    Ok(())
}

