#[tokio::test]
#[ignore = "paired statement-cache experiment"]
async fn benchmark_statement_cache_collection() {
    use std::time::Instant;
    let counts = std::env::var("CASITA_COLLECTION_COUNTS").unwrap_or_else(|_| "256,65537".into());
    let iterations: usize = std::env::var("CASITA_COLLECTION_ITERATIONS")
        .unwrap_or_else(|_| "12".into()).parse().unwrap();
    for count in counts.split(',').map(|v| v.parse::<usize>().unwrap()) {
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join("metadata.sqlite");
        let store = TursoMetadataStore::open(&path).await.unwrap();
        let mut revision = store.snapshot().await.unwrap().revision();
        let mut retained = BTreeSet::new();
        for first in (0..count).step_by(1024) {
            let mut mutation = MetadataMutation::new();
            for index in first..(first + 1024).min(count) {
                let object = blob(&(index as u64).to_le_bytes()).await;
                retained.insert(object.record().key().clone());
                mutation.add_object(object);
            }
            revision = store.commit(&revision, mutation).await.unwrap().revision;
        }
        let retained: Arc<dyn RetainedObjects> = Arc::new(retained);
        let mut samples = Vec::new();
        for iteration in 0..iterations + 1 {
            let mutation = MetadataMutation::install_retained_source(retained.clone());
            let started = Instant::now();
            let committed = store.commit(&revision, mutation).await.unwrap();
            let nanos = started.elapsed().as_nanos() as u64;
            assert_eq!(committed.objects_removed, 0);
            revision = committed.revision;
            samples.push(serde_json::json!({"iteration": iteration, "warm": iteration > 0, "nanos": nanos}));
        }
        drop(store);
        let reopened = TursoMetadataStore::open(&path).await.unwrap();
        let snapshot = reopened.snapshot().await.unwrap();
        assert_eq!(snapshot.revision(), revision);
        let actual = snapshot.objects().map_ok(|object| object.key().clone())
            .try_collect::<BTreeSet<_>>().await.unwrap();
        assert_eq!(actual.len(), count);
        for key in &actual {
            assert!(retained.contains(key).await.unwrap());
        }
        println!("collection_sample {}", serde_json::json!({"count": count, "iterations": iterations,
            "samples": samples, "correctness": "zero removals, exact reopened inventory and revision"}));
    }
}
